const updateUserProfile = `-- name: UpdateUserProfile :one
UPDATE users
SET name       = $2,
    email      = $3,
    avatar_url = NULLIF($4::text, '')
WHERE id = $1 AND deleted_at IS NULL
RETURNING id, email, name, password_hash, avatar_url, is_shadow, deleted_at, created_at
`

type UpdateUserProfileParams struct {
	ID        string
	Name      string
	Email     string
	AvatarURL string
}

type UpdateUserProfileRow struct {
	ID           string
	Email        string
	Name         string
	PasswordHash string
	AvatarURL    *string
	IsShadow     bool
	DeletedAt    pgtype.Timestamptz
	CreatedAt    pgtype.Timestamptz
}

// One statement, so a taken email (23505 on users_email_key) rolls the whole
// profile update back — no half-applied name change (US-AD89 AC2/AC3). The
// `deleted_at IS NULL` guard is what turns a closed account into zero rows.
//
// The cast on $4 is load-bearing: `NULLIF($4, ”)` alone gives sqlc no type to
// infer, so it falls back to a positional `Column4 interface{}` whose exact
// spelling drifts between sqlc releases and breaks the caller. `sqlc.arg` names
// the parameter and `::text` pins the type, so the generated field is stable.
func (q *Queries) UpdateUserProfile(ctx context.Context, arg UpdateUserProfileParams) (UpdateUserProfileRow, error) {
	row := q.db.QueryRow(ctx, updateUserProfile,
		arg.ID,
		arg.Name,
		arg.Email,
		arg.AvatarURL,
	)
	var i UpdateUserProfileRow
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.Name,
		&i.PasswordHash,
		&i.AvatarURL,
		&i.IsShadow,
		&i.DeletedAt,
		&i.CreatedAt,
	)
	return i, err
}

const upsertDailyBoardCost = `-- name: UpsertDailyBoardCost :exec
INSERT INTO daily_board_costs (org_id, board_id, day, total_micros, tokens_in, tokens_out, updated_at)
VALUES ($1, $2, (now() AT TIME ZONE 'UTC')::date, $3, $4, $5, now())
ON CONFLICT (board_id, day) DO UPDATE
SET total_micros = daily_board_costs.total_micros + EXCLUDED.total_micros,
    tokens_in    = daily_board_costs.tokens_in    + EXCLUDED.tokens_in,
    tokens_out   = daily_board_costs.tokens_out   + EXCLUDED.tokens_out,
    updated_at   = now()
`

type UpsertDailyBoardCostParams struct {
	OrgID       string
	BoardID     string
	TotalMicros int64
	TokensIn    int64
	TokensOut   int64
}

// 4c/5.3: agregat biaya harian per board. Di-UPSERT setiap step selesai, jadi
// dispatcher tidak perlu menjumlahkan ledger_entries tiap tick.
func (q *Queries) UpsertDailyBoardCost(ctx context.Context, arg UpsertDailyBoardCostParams) error {
	_, err := q.db.Exec(ctx, upsertDailyBoardCost,
		arg.OrgID,
		arg.BoardID,
		arg.TotalMicros,
		arg.TokensIn,
		arg.TokensOut,
	)
	return err
}

const upsertModelPrice = `-- name: UpsertModelPrice :one

INSERT INTO agent_model_prices (
    id, org_id, model, input_micros_per_1m, output_micros_per_1m,
    cached_micros_per_1m, reasoning_micros_per_1m, cache_write_micros_per_1m, created_by
)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
ON CONFLICT (org_id, model) DO UPDATE SET
    input_micros_per_1m       = EXCLUDED.input_micros_per_1m,
    output_micros_per_1m      = EXCLUDED.output_micros_per_1m,
    cached_micros_per_1m      = EXCLUDED.cached_micros_per_1m,
    reasoning_micros_per_1m   = EXCLUDED.reasoning_micros_per_1m,
    cache_write_micros_per_1m = EXCLUDED.cache_write_micros_per_1m,
    updated_at                = now()
RETURNING id, org_id, model, input_micros_per_1m, output_micros_per_1m,
          cached_micros_per_1m, reasoning_micros_per_1m, cache_write_micros_per_1m,
          created_by, created_at, updated_at
`

